typedef struct HoverboardVars {
    Vec4 last_pos;           /* 0x00: the moby's position last frame */
    Vec4 home_pos;           /* 0x10: where the board returns when it is released */
    u8 pad_20[0x30];
    s32 unk50;               /* 0x50: nonzero keeps it from returning home */
} HoverboardVars;

/* func_L05_002F9BA0 -- src/overlays/shared/vendor_002CF2C0.c (functional C for the port, not a match)
 * Hoverboard moby update (class 439, levels 05 and 16). State 0: when Ratchet comes within 5.5 (and
 * the story flag D_L05_0015F6B0 is at least 4, and he is not in movement group 0x15 or 0x16) it
 * becomes his board (hero +0x86C), plays sound 0x6B, saves its position as home (pvars +0x10) and
 * goes to state 1. State 1: may play the 0x138F hint line; when Ratchet leaves group 0x16 it goes
 * back to 0, returning home unless pvars +0x50. Every frame it then works out its velocity from the
 * last position (pvars +0x00) and, when slow and not suppressed (+0xBC == 2), emits its hover
 * exhaust particles (two kinds while moving, +0xBC != 0).
 * From the staged near miss (nonmatching/shared/func_L05_002F9BA0.c); fixed: state 0 saves the
 * position into pvars +0x10 (the near miss copied the other way), and the state tests.
 * equiv: NEAR (all copies: retail rebuilds moby + 0x10 where this keeps it). */
void hoverboard_update(unsigned char *moby) {
    HoverboardVars *data;
    char *hero_pos;
    struct Hero *player;
    float delta[4], position[4], effect_position[4], offset[4], second_position[4];
    float delta_length;
    int one = 1;
    int st;

    data = (HoverboardVars *)((struct Moby *)moby)->pvars;
    st = ((struct Moby *)moby)->state;
    switch (st) {
    case 0:
        hero_pos =&((struct Hero *)((char *)&hero_globals_base + 0xE1D))->motion.pos;
        if (FastVecDist(hero_pos, &((struct Moby *)moby)->pos) < 5.5f) {
            if (*(int *)&rilgar_frame_count >= 4) {
                int grp;
                player = (struct Hero *)(hero_pos - 0x80);
                grp = player->state.control_mode;
                if (grp != 0x15) if (grp != 0x16) {
                    player->hoverboard_moby = moby;
                    ((int (*)(int, int))Hero_TryMoveStateL05)(0x6B, 1);
                    if (data->unk50 == 0) {
                        qcopy(&data->home_pos, &((struct Moby *)moby)->pos);
                    }
                    ((struct Moby *)moby)->state = one;
                    ((struct Moby *)moby)->update_dist = 0xFF;
                }
            }
        }
        break;
    case 1: {
        if (data->unk50 == 0) {
            if (special_items_base[0x13B] != 0) {
                if (*(unsigned short *)(help_stats_base + 0x31D) == 0) {
                    if (hoverboard_race_finished != 0) {
                        struct Hero *h = (struct Hero *)(hero_globals_base + 0xE1D);
                        int ret = scale_ticks(0x4B0);
                        if (ret < h->control_mode_timer) {
                            extern unsigned short hoverboard_race_help_shown_count[];
                            if (hoverboard_race_help_shown_count[0] == 0) {
                                Help_Request(0x138F, 0x5F);
                            }
                        }
                    }
                }
            }
        }
        {
            struct Hero *h2 = (struct Hero *)(hero_globals_base + 0xE1D);
            if (h2->state.control_mode != 0x16) {
                ((struct Moby *)moby)->update_dist = 0x10;
                if (data->unk50 != 0) {
                    ((struct Moby *)moby)->state = 0;
                } else {
                    qcopy(&((struct Moby *)moby)->pos, &data->home_pos);
                    ((struct Moby *)moby)->state = 0;
                }
            }
        }
        break;
    }
    case 2:
        break;
    }

    FastVecSub(delta, &((struct Moby *)moby)->pos, data);
    qcopy(&data->last_pos, &((struct Moby *)moby)->pos);
    delta_length = FastVecLength(delta);
    if (((struct Moby *)moby)->command != 2 && delta_length < 2.0f) {
        float distance_scale;
        float angle;
        Moby_GetJointWorldPos(moby, *(int *)&rilgar_frame_count & 1, position);
        angle = random_angle_radians();
        distance_scale = g_frame_time * 0.25f;
        vec_scale_to_length(effect_position, &((struct Moby *)moby)->rot_row2, distance_scale * FastCos(angle));
        vec_scale_to_length(offset, &((struct Moby *)moby)->rot_row1, distance_scale * FastSin(angle));
        FastVecAdd(effect_position, effect_position, delta);
        FastVecAdd(effect_position, effect_position, offset);
        qcopy(effect_position, delta);
        effect_position[3] = (float)*(int *)&hoverboard_effect_displacement_w_gp;
        if (((struct Moby *)moby)->command == 0) {
            int a;
            int b;
            int c;
            a = scale_ticks(10);
            b = scale_ticks(13);
            c = rand_range(a, b);
            PartType04Spawn(position, effect_position, *(int *)&rilgar_hoverboard_trail_start_color, *(int *)&rilgar_hoverboard_trail_end_color, c, 15, 15, 1);
        } else {
            int a;
            int b;
            int c;
            FastVecScale(second_position, delta, 0.92f);
            a = scale_ticks(0xF);
            b = scale_ticks(0x12);
            c = rand_range(a, b);
            PartType04Spawn(position, second_position, 0x5032F0D2, *(int *)&rilgar_hoverboard_trail_end_color, c, 0x1E, 0x14, 1);
            {
                int a2;
                int b2;
                int c2;
                a2 = scale_ticks(8);
                b2 = scale_ticks(0x11);
                c2 = rand_range(a2, b2);
                PartType21Spawn(position, effect_position, *(int *)&rilgar_hoverboard_trail_start_color, *(int *)&rilgar_hoverboard_trail_end_color, c2, 1, 15000.0f);
            }
        }
    }
    ((struct Moby *)moby)->command = 0;
}
